insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('c3f3bc41-b996-535d-bc90-7c74ab056d33', '8f8a4c97-4077-5352-b040-a22de57f1b7e', 'The past that describes', 'The preterite says what happened; the **imperfect** says what things were like: **era** (I was / he was), **tenía** (I had), **vivía** (I lived), **iba** (I went, I used to go). *Cuando era chico vivía en Rosario* — both verbs describe, nothing *happens*.', 'draft'),
  ('d8ff1d8e-820e-58b5-90e2-11bcfa7d7941', '8f8a4c97-4077-5352-b040-a22de57f1b7e', 'Yo and él share a form', 'In the imperfect, *yo* and *él/ella* are the same word: **era** is *I was* and *he was*. The subject — or the story — tells you which. **De chico** is *as a kid*.', 'draft'),
  ('5cb4a4ed-8115-5eba-b4b6-dffd001a2744', '38114afb-c035-5ae5-956f-723c4f408a0d', '-aba and -ía', 'Regular verbs make the imperfect with **-aba** (*jugaba, laburaba*) or **-ía** (*comía, salía*). Only *nosotros* takes an accent: **jugábamos**, **salíamos**.', 'draft'),
  ('6d33c712-30bd-5a0b-b7fc-41b7df68c612', '38114afb-c035-5ae5-956f-723c4f408a0d', 'Used to', 'Where English says *used to*, Spanish just uses the imperfect: **Siempre tomaba mate con mi abuela** — *I always used to have mate with my grandma*.', 'draft'),
  ('1ff3fc85-22c8-5185-8a7a-91d25977fbb5', '520a3c73-f830-5ea8-bb7f-36b6b5a53614', 'The scene and the event', 'The imperfect paints the scene, the preterite is what happens in it: **Estaba en el subte cuando me llamó Sofi** — *I was on the subway when Sofi called me*.', 'draft'),
  ('636b7821-633f-5fb5-94b1-ae095af46302', '520a3c73-f830-5ea8-bb7f-36b6b5a53614', 'Había, hacía', '**Había** is *there was, there were*; **hacía calor** is *it was hot*. **Mientras** — *while* — joins two things going on at once.', 'draft'),
  ('63f495cd-a71f-55ee-ae30-b4789e91cebd', '28d6c921-dae2-50d2-b6a0-a5e2423428a6', 'Pedir', '**Pido** (I order), **pedís** (you order); in the past **pedí**, **pediste**, and — with an *i* — **pidió**. At the table: **¿Me traés la carta?** and, at the end, **la cuenta**.', 'draft'),
  ('2910b1f9-2188-52b3-b99b-5ff32f745b64', '28d6c921-dae2-50d2-b6a0-a5e2423428a6', 'Propina', 'The tip is **la propina**, usually ten per cent and in cash. **¿Compartimos?** — *shall we share?* — is how two people order one enormous *bife*.', 'draft'),
  ('e4c89765-3136-5623-8e35-8eb3d88cd738', 'f901adf3-4ac4-5208-8cac-9261ab754144', 'Tipo ocho', '**Tipo** before a time is *around*: **tipo ocho** — *around eight*, which in Buenos Aires means eight-fifteen at the earliest. **En punto** is *on the dot*, and rarer.', 'draft'),
  ('6e6d5a70-d67b-5f52-aa08-3decebcbcd88', 'f901adf3-4ac4-5208-8cac-9261ab754144', 'Avisame', '**Avisame cuando llegás** — *let me know when you get there*. **Te aviso** — *I''ll let you know*.', 'draft'),
  ('a3d8add9-3af2-5335-9dc3-fda0446ac1a7', '364e1a73-f26c-5d78-9757-4d096939ebda', 'Christmas in summer', '**Navidad** falls in the heat, so it is often an *asado*, cider and **pan dulce** at midnight, and a **brindis** — *¡salud!* — before the fireworks.', 'draft'),
  ('3b3cb9f8-ec4a-523f-9a40-289a5d60cc43', '364e1a73-f26c-5d78-9757-4d096939ebda', 'Los ñoquis del 29', 'On the 29th of every month many families eat **ñoquis** with a banknote under the plate, for luck. A **feriado** is a public holiday, and there are plenty of them.', 'draft'),
  ('c6f60906-d59e-542e-8047-b8fad681b872', 'a6c406c0-0103-5fcc-9871-5e1bc85a3833', 'Ponerse: to get (a feeling)', '**Me puse nervioso** — *I got nervous*; **se puso contenta** — *she got happy*. The feeling changes, so it''s *ponerse*, in the preterite.', 'draft'),
  ('06c86ef5-7846-5ed7-8073-f632d15a579c', 'a6c406c0-0103-5fcc-9871-5e1bc85a3833', 'Me enojé', 'The feeling verbs keep their pronoun in the past too: **me enojé**, **te asustaste**, **se preocupó**.', 'draft'),
  ('a5a666cc-13f5-582b-a31d-e3454f6aea44', '2902c53a-0143-5823-b423-fd9fe3dc2295', 'Voy a…', 'Porteños talk about the future with **ir a**: **voy a laburar**, **vamos a comer**. *Next week* is **la semana que viene**, *next year* **el año que viene**.', 'draft'),
  ('40e8fd4a-7fef-5c78-a666-03e64f6b1eed', '2902c53a-0143-5823-b423-fd9fe3dc2295', 'Tengo ganas', '**Tengo ganas de ir a la playa** — *I feel like going to the beach*. **Pienso ir** — *I''m planning to go*.', 'draft'),
  ('c9b7d55e-27f0-5b3b-9f11-ed3849a02af0', 'f2432d21-cbd5-5f7f-aec5-c958b3d7f626', 'Extrañar', '**Extraño a mi vieja** — *I miss my mum*. Not *echar de menos*: that is Spain''s, and here nobody says it.', 'draft'),
  ('72734c3b-aa10-5b4c-819d-56584b23250e', 'f2432d21-cbd5-5f7f-aec5-c958b3d7f626', 'Me mudé', '**Me mudé** — *I moved (house)*; **nos mudamos** — *we moved*. The **mudanza** is the move itself, and always a *quilombo*.', 'draft'),
  ('ce04f326-dc62-5b78-b284-566e6fd63f08', 'b2e41f0e-04f0-5a3b-94eb-850cd2d57575', '¿Te acordás?', '**¿Te acordás cuando…?** opens every memory at a family asado. **Me acuerdo** — *I remember*; **no me acuerdo** — *I don''t remember*.', 'draft'),
  ('f03770e9-f70b-5bf7-9fc5-3507aa771946', 'b2e41f0e-04f0-5a3b-94eb-850cd2d57575', 'Antes era distinto', '**Antes era distinto** — *it used to be different*. **¡Qué épocas!** — *those were the days!* — closes it.', 'draft')
